#!/usr/bin/python3
"""Atomically upgrade the catalog database from schema v1 to v2."""

import os
import sqlite3

BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DB_PATH = os.path.join(BASE_DIR, "catalog.db")


def schema_version(db):
    rows = db.execute("SELECT version FROM schema_version").fetchall()
    if len(rows) != 1 or not isinstance(rows[0][0], int):
        raise RuntimeError("schema_version must contain exactly one integer row")
    return rows[0][0]


def validate_v2(db):
    columns = {row[1]: row for row in db.execute("PRAGMA table_info(products)")}
    required = {"id", "description", "price_cents"}
    if not required.issubset(columns):
        raise RuntimeError("schema v2 is missing required products columns")
    price = columns["price_cents"]
    if price[2].upper() != "INTEGER" or price[3] != 1 or str(price[4]).strip("'\"") != "0":
        raise RuntimeError("schema v2 has an invalid price_cents definition")
    invalid = db.execute(
        "SELECT COUNT(*) FROM products WHERE price_cents IS NULL OR price_cents < 0"
    ).fetchone()[0]
    if invalid:
        raise RuntimeError("schema v2 contains invalid product prices")


def upgrade():
    db = sqlite3.connect(DB_PATH, isolation_level=None)
    try:
        db.execute("BEGIN IMMEDIATE")
        version = schema_version(db)
        if version == 1:
            db.execute(
                "ALTER TABLE products ADD COLUMN price_cents INTEGER "
                "NOT NULL DEFAULT 0 CHECK (price_cents >= 0)"
            )
            validate_v2(db)
            changed = db.execute(
                "UPDATE schema_version SET version = 2 WHERE version = 1"
            ).rowcount
            if changed != 1:
                raise RuntimeError("schema_version was not advanced exactly once")
        elif version == 2:
            validate_v2(db)
        else:
            raise RuntimeError("unsupported schema version: %r" % (version,))
        db.commit()
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


if __name__ == "__main__":
    upgrade()
